import{_ as t,o as n,c as o,a2 as i}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/plugins.md","filePath":"user-guide/settings/plugins.md","lastUpdated":1788190459000}'),a={name:"user-guide/settings/plugins.md"};function s(r,e,l,d,g,c){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>Lertaro features a modular plugin architecture. Core extensions, native C# plugins, and third-party community extensions can all be viewed, configured, and managed in the Plugin Center under <strong>Settings → Plugins</strong>.</p><h2 id="_1-page-layout-sdk-version" tabindex="-1">1. Page Layout &amp; SDK Version <a class="header-anchor" href="#_1-page-layout-sdk-version" aria-label="Permalink to &quot;1. Page Layout &amp; SDK Version&quot;">​</a></h2><ul><li><strong>Plugin SDK Badge</strong>: The top-right badge displays the currently loaded <code>Lertaro.PluginSdk</code> version. Clicking it opens the <a href="./../../dev-guide/"><strong>Developer Guide</strong></a> directly.</li><li><strong>Independent Dual-Pane Layout</strong>: The left pane lists all installed plugins, while the right pane renders details and configuration forms for the selected plugin, with independent scrolling.</li></ul><h2 id="_2-plugin-details-component-toggles" tabindex="-1">2. Plugin Details &amp; Component Toggles <a class="header-anchor" href="#_2-plugin-details-component-toggles" aria-label="Permalink to &quot;2. Plugin Details &amp; Component Toggles&quot;">​</a></h2><p>Clicking any plugin on the left displays its icon, name, version, and overview in the right pane:</p><h3 id="details-tab" tabindex="-1">Details Tab <a class="header-anchor" href="#details-tab" aria-label="Permalink to &quot;Details Tab&quot;">​</a></h3><ul><li><strong>Component Grouping</strong>: Lists all registered functional components (Search Sources, Action Providers, Quick Navigation Providers, Preview Handlers, etc.).</li><li><strong>Individual Component Switches</strong>: Non-essential components feature an <strong>Enable/Disable Checkbox</strong>; mandatory system components display a lock icon and cannot be disabled.</li><li><strong>Select All / Deselect All</strong>: Convenient links appear beside group headers containing multiple toggleable components.</li><li><strong>Component Tooltips</strong>: Hover over the <strong>(!)</strong> icon next to any component to inspect its implementation details and activation triggers.</li></ul><h3 id="configure-tab" tabindex="-1">Configure Tab <a class="header-anchor" href="#configure-tab" aria-label="Permalink to &quot;Configure Tab&quot;">​</a></h3><ul><li><strong>Embedded Configuration Forms</strong>: Custom settings are rendered directly within the settings pane without opening modal dialogs. Supports text boxes, numerical steppers, toggles, dropdowns, and grouped sub-tabs.</li><li><strong>Safe Staging &amp; Rollback</strong>: Modifications are kept in memory until <strong>OK</strong> is clicked; switching plugins or navigating away automatically rolls uncommitted edits back to their saved state.</li></ul><h2 id="_3-flow-launcher-community-ecosystem-bridge" tabindex="-1">3. Flow Launcher Community Ecosystem Bridge <a class="header-anchor" href="#_3-flow-launcher-community-ecosystem-bridge" aria-label="Permalink to &quot;3. Flow Launcher Community Ecosystem Bridge&quot;">​</a></h2><p>In addition to native plugins built against <code>Lertaro.PluginSdk</code>, Lertaro includes a built-in <strong>Flow Launcher Bridge</strong> providing native-grade compatibility for the expansive Flow Launcher plugin community.</p><h3 id="multi-language-isolated-runtimes" tabindex="-1">Multi-Language Isolated Runtimes <a class="header-anchor" href="#multi-language-isolated-runtimes" aria-label="Permalink to &quot;Multi-Language Isolated Runtimes&quot;">​</a></h3><ul><li><strong>Full Language Compatibility</strong>: Seamlessly executes Flow Launcher plugins written in <strong>C# (.NET)</strong>, <strong>Python 3.12</strong>, <strong>Node.js v20 LTS</strong>, and standalone executables (<code>.exe</code>).</li><li><strong>Isolated Self-Contained Environments</strong>: Python (<code>FlowData\\PythonEmbeded-{arch}</code>) and Node.js (<code>FlowData\\NodeEmbeded-{arch}</code>) runtimes are automatically deployed on-demand within Lertaro&#39;s data directory, ensuring zero contamination of system PATH.</li><li><strong>Automated Dependency Management</strong>: Automatically installs Python <code>pip</code> packages from <code>requirements.txt</code> or Node.js <code>npm</code> dependencies from <code>package.json</code> silently in the background upon first load.</li></ul><h3 id="online-store-cli-package-management" tabindex="-1">Online Store &amp; CLI Package Management <a class="header-anchor" href="#online-store-cli-package-management" aria-label="Permalink to &quot;Online Store &amp; CLI Package Management&quot;">​</a></h3><p>Manage Flow plugins directly from the Lertaro search box:</p><ul><li><strong><code>flow install &lt;keyword&gt;</code></strong>: Searches the official Flow.Launcher online repository, downloads, extracts, deploys, and bootstraps dependencies with a single click.</li><li><strong><code>flow update</code></strong>: Checks for updates across all installed Flow plugins and upgrades them in-place.</li><li><strong><code>flow uninstall &lt;plugin&gt;</code></strong>: Safely uninstalls plugins and cleans up local directories.</li><li><strong>Manual Installation</strong>: Drop third-party plugin folders directly into <code>&lt;UserData&gt;\\FlowData\\Plugins\\</code>.</li></ul><h3 id="configuration-actionkeywords-interactive-previews" tabindex="-1">Configuration, ActionKeywords &amp; Interactive Previews <a class="header-anchor" href="#configuration-actionkeywords-interactive-previews" aria-label="Permalink to &quot;Configuration, ActionKeywords &amp; Interactive Previews&quot;">​</a></h3><ul><li><strong>Centralized ActionKeywords</strong>: Under <strong>Settings → Plugins → Flow Launcher Bridge → Configure</strong>, toggle individual Flow plugins and customize their <strong>ActionKeyword</strong>. Settings persist cleanly in <code>FlowData\\Settings\\Plugins.json</code>.</li><li><strong>Dynamic Configuration Forms</strong>: Fully supports YAML/JSON template forms (<code>SettingsTemplate.yaml</code>/<code>.json</code>) and C# WPF panels (<code>ISettingProvider</code>), automatically styled to match the active theme with full i18n support.</li><li><strong>WebView2 Rich Previews</strong>: Renders complex interactive preview panels (e.g. MDict dictionary definitions, live weather, API debuggers, webpage snapshots) seamlessly inside QuickLook with automatic dark/light styling and custom scrollbars.</li><li><strong>Deep Host Integration</strong>: Flow plugins opening directories automatically respect the host&#39;s configured third-party file manager, message boxes render in host-native themed dialogs, and internal plugin logs flow directly into the Settings log viewer.</li><li><strong>Quick Overview</strong>: Type <code>flow</code> into the search box to list all loaded Flow plugins and their action keywords; selecting a plugin opens its corresponding configuration group in Settings.</li></ul><h2 id="_4-content-search" tabindex="-1">4. Content Search <a class="header-anchor" href="#_4-content-search" aria-label="Permalink to &quot;4. Content Search&quot;">​</a></h2><p>The <strong>Content Search</strong> plugin searches text inside configured local documents. Open its <strong>Configure</strong> tab to set the trigger keyword, monitored folders, indexed extensions, per-file size limit, index size cap, and excluded full-path regular expressions. The default trigger is <code>cs</code>, so <code>cs project plan</code> searches document content and shows matching files with snippets.</p><p>The configuration also provides <strong>Clear Index</strong> and <strong>Rebuild Index</strong>. Clear removes only the content index, while Rebuild removes it and scans all monitored folders again. Neither action removes Lertaro&#39;s normal filename index.</p>',22)])])}const h=t(a,[["render",s]]);export{p as __pageData,h as default};
